import{z as i,x as A,o as E,c,q as t,j as l,D as e,d as s,s as n,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"内核漏洞类别","description":"","frontmatter":{"title":"内核漏洞类别","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-kernel-vuln-classes.md","filePath":"cs/ss-kernel-vuln-classes.md","lastUpdated":1791063341000}'),d={name:"cs/ss-kernel-vuln-classes.md"};function p(h,a,f,u,m,C){const B=A("Mermaid");return E(),c("div",null,[a[2]||(a[2]=t('<h1 id="内核漏洞类别" tabindex="-1">内核漏洞类别 <a class="header-anchor" href="#内核漏洞类别" aria-label="Permalink to &quot;内核漏洞类别&quot;">​</a></h1><div class="epigraph"><p>用户态的内存错误多半是崩溃；同一个错误落进内核就换了名字：提权。分类不是为了背清单，而是为了让每一类都对得上一条确定的缓解。</p><footer>—— 据 Chou et al., An Empirical Study of Operating System Errors, SOSP 2001；CWE 常见弱点枚举整理</footer></div><p><a href="/cs/ce-map">上一课</a>给「密码学工程」收束：八层地图从选型排到迁移，决策先归层再查课；全部事故同机制——确定性冒充随机性，或随机性缺乏合同；全部防御同机制——把正确做法变成默认路径，在接口层没收犯错机会。主干课里 <a href="/cs/jop-cop">JOP 与 COP</a>、<a href="/cs/heap-uaf">堆 UAF</a>、<a href="/cs/format-string">格式化字符串</a>给过利用侧的原语，<a href="/cs/selinux-type-enforcement">SELinux 类型强制</a>给过策略侧的答案，但它们都以用户态为默认舞台。本课是「系统安全深化」的第一课，转向舞台本身：内核。缺口是给内核漏洞钉一张类别表——按根因分类，再映射到攻击者实际拿到的东西——本课程后面八课的沙箱、语言、硬件、移动与云，都按这张表对号入座。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核不是「更大的用户程序」，三个结构性差别使它自成一个威胁模型。其一，特权终点：内核跑在<a href="/cs/privilege-rings">特权环</a>的顶层，<a href="/cs/user-kernel-split">用户-内核分界</a>处一次失守之后没有第二道墙，攻击者拿到的不是某个进程的权限，而是全系统。其二，面积：几千万行 C，驱动占大头；Chou 等对 Linux 与 OpenBSD 的实证统计给出，驱动代码的缺陷密度是核心代码的数倍。其三，并发：中断、抢占与多核让「检查时刻」与「使用时刻」天然分离，<a href="/cs/toctou">TOCTOU</a> 在这里不是边角情况而是日常。</p><p>缺口因此是：把 CVE 流水账整理成按根因分类的表，使「这一类 bug 由什么缓解兜住」有确定答案，而不是逐案打补丁。</p><h3 id="根因轴与原语轴" tabindex="-1">根因轴与原语轴 <a class="header-anchor" href="#根因轴与原语轴" aria-label="Permalink to &quot;根因轴与原语轴&quot;">​</a></h3><p>分类需要两条轴。根因轴问代码错在哪：空间错误（越界读写）、时间错误（释放后使用、双重释放）、未初始化、整数错误（长度计算回绕）、双取（double-fetch，同一内存被检查与使用各取一次而其间可被改写——TOCTOU 的内核特化）、引用计数错，以及不碰内存的逻辑类（缺权限检查）。原语轴问攻击者拿到什么：内核任意读写、任意执行、信息泄漏——<a href="/cs/aslr-nx">ASLR 与 NX</a> 讲过泄漏如何吃掉随机化的熵——以及终局原语：改写凭证结构完成提权。</p><p><span class="marginnote">Chou et al. 的统计里，驱动代码的缺陷密度是核心内核的 3 到 7 倍；「驱动是内核攻击面的主体」从 2001 年至今没有翻案，syzbot 时代的报告分布仍然如此。</span></p><p><span class="marginnote">双取可以翻译成「先查后用，但查的和用的不是同一份」：内核以为自己是唯一读者，可用户页随时能被用户进程改写。类比成海关查验护照后把护照还给你、登机时再收走一次——中间那段时间护照被换了，第一次查验就白做了。防御因此是把值复制进内核自己的变量，只读这一份。</span></p><p><span class="marginnote">整数回绕的数字实例：32 位下，个数 \\(n\\) 取 1073741825、单项 4 字节，\\(n \\times 4\\) 的真实结果是 4294967300，截断成 32 位后只剩 4——分配一个 4 字节的缓冲，随后却拷入约 4 GB。攻击者专挑这种「乘完变小」的位置，所以审计时先看长度乘法，再看有没有溢出检查。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每类根因配一个内核特有的实例。空间错误：系统调用把用户传入的长度直接用于栈缓冲拷贝；<code>copy_from_user</code> 这类原语的存在理由，就是把「用户指针不可信」钉成内核调用约定。时间错误：引用计数少加一次，对象在他人仍持有时释放——<a href="/cs/heap-uaf">堆 UAF</a> 的机制原样成立，只是槽位换成了内核对象。双取：先校验 <code>$\\mathrm{size} \\lt \\mathrm{LIMIT}$</code>，再从同一用户页重读 <code>size</code> 去用，两次读之间用户改写、检查作废，防御是把值读进本地副本只读一次。整数错误：<code>$n \\times \\mathrm{sizeof}(\\mathrm{item})$</code> 回绕成小值，小缓冲装下大拷贝。未初始化：栈上结构体带洞，回传用户即成内核地址泄漏，<a href="/cs/kernel-hardening">内核加固</a>的清栈与 KASLR 正是补这一格。逻辑类：少一次 <code>capable()</code> 检查，与内存无关，不崩溃，fuzzing 抓不到，只能靠审计与<a href="/cs/selinux-type-enforcement">类型强制</a>兜底。</p>',13)),(E(),l(o,null,{default:e(()=>[n(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20INPUT%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%E8%BE%93%E5%85%A5%EF%BC%9Asyscall%20%2F%20%E9%A9%B1%E5%8A%A8%20%2F%20%E6%96%87%E4%BB%B6%E6%A0%BC%E5%BC%8F%22%5D%20--%3E%20CLS%5B%22%E6%A0%B9%E5%9B%A0%E7%B1%BB%EF%BC%9A%E7%A9%BA%E9%97%B4%20%2F%20%E6%97%B6%E9%97%B4%20%2F%20%E5%8F%8C%E5%8F%96%20%2F%20%E6%95%B4%E6%95%B0%20%2F%20%E6%9C%AA%E5%88%9D%E5%A7%8B%E5%8C%96%20%2F%20%E9%80%BB%E8%BE%91%22%5D%0A%20%20CLS%20--%3E%20PRIM%5B%22%E5%8E%9F%E8%AF%AD%EF%BC%9A%E5%86%85%E6%A0%B8%E8%AF%BB%E5%86%99%20%2F%20%E6%89%A7%E8%A1%8C%20%2F%20%E4%BF%A1%E6%81%AF%E6%B3%84%E6%BC%8F%22%5D%0A%20%20PRIM%20--%3E%20ESC%5B%22%E6%94%B9%E5%86%99%E5%87%AD%E8%AF%81%EF%BC%9A%E6%8F%90%E6%9D%83%22%5D%0A%20%20ESC%20--%3E%20WALL%5B%22%E7%89%B9%E6%9D%83%E7%8E%AF%E4%B9%8B%E4%B8%8B%E6%B2%A1%E6%9C%89%E7%AC%AC%E4%B8%89%E9%81%93%E5%A2%99%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[s("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"两条轴连成一条链：根因给原语，原语给提权。缓解的分工因此可以逐格核对：空间与时间类交给语言和检测器（内存安全语言一课），信息泄漏交给清栈与随机化（内核加固课），逻辑类只能交给权限模型，而沙箱一课回答「以上全部失败之后，爆炸半径还剩多少」。内核漏洞的特殊性不在错误本身——与用户态是同一批根因——而在链条终点没有缓冲：每一环都直接通向全系统，所以每一环都值得单独设防。",-1)),(E(),l(o,null,{default:e(()=>[n(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20MEM%5B%22%E7%A9%BA%E9%97%B4%20%2F%20%E6%97%B6%E9%97%B4%E9%94%99%E8%AF%AF%22%5D%20--%3E%20LANG%5B%22%E5%86%85%E5%AD%98%E5%AE%89%E5%85%A8%E8%AF%AD%E8%A8%80%E4%B8%8E%E6%A3%80%E6%B5%8B%E5%99%A8%22%5D%0A%20%20LEAK%5B%22%E6%9C%AA%E5%88%9D%E5%A7%8B%E5%8C%96%E6%B3%84%E6%BC%8F%22%5D%20--%3E%20HARD%5B%22%E6%B8%85%E6%A0%88%E4%B8%8E%20KASLR%20%E5%8A%A0%E5%9B%BA%22%5D%0A%20%20LOGIC%5B%22%E9%80%BB%E8%BE%91%E7%B1%BB%EF%BC%9A%E7%BC%BA%E6%9D%83%E9%99%90%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20TE%5B%22%E6%9D%83%E9%99%90%E6%A8%A1%E5%9E%8B%E4%B8%8E%E7%B1%BB%E5%9E%8B%E5%BC%BA%E5%88%B6%22%5D%0A%20%20RES%5B%22%E4%BB%A5%E4%B8%8A%E5%85%A8%E6%BC%8F%EF%BC%9A%E4%BB%BB%E4%B8%80%E5%BE%97%E6%89%8B%22%5D%20--%3E%20SBX%5B%22%E6%B2%99%E7%AE%B1%E9%99%90%E5%88%B6%E7%88%86%E7%82%B8%E5%8D%8A%E5%BE%84%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">这张分工表的直觉：内存类漏洞像「墙被打穿」，要用更结实的材料（安全语言）砌墙；泄漏像「屋里东西被看走」，要拉窗帘（清栈、随机化）；逻辑类像「门根本没锁」，任何材料都帮不上，只能靠制度（权限模型）管人。初学者容易以为给逻辑漏洞上 fuzzing 就能覆盖——实际上不崩溃、不报错的路径，fuzzing 的大部分信号都是哑的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写利用技术本身：ROP/JOP 的缝合与堆布局雕琢主干已给；模糊测试如何自动发现这些类别留给模糊测试一课；侧信道与瞬时执行是另一条泄漏通道，主干已有专课；驱动与固件的供应链问题留给供应链课。具体 CVE 来来去去，类别表是本课留下的稳定物。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核威胁模型的三个差别：特权终点无缓冲、驱动占攻击面主体、并发使检查与使用分离。</li><li>分类用两条轴：根因（空间/时间/双取/整数/未初始化/逻辑）与原语（读写/执行/泄漏/提权）。</li><li>双取是 TOCTOU 的内核特化；未初始化泄漏喂给 KASLR 攻击；逻辑类不崩溃，只能靠权限模型。</li><li>缓解按类别分工：语言管内存类、加固管泄漏、TE 管逻辑类、沙箱管剩余爆炸半径。</li><li>本课程后课按这张表对号入座，逐格交代各自的兜法。</li><li>出处：Chou et al., SOSP 2001；CWE；对照 <a href="/cs/heap-uaf">heap-uaf</a>、<a href="/cs/toctou">toctou</a>、<a href="/cs/kernel-hardening">kernel-hardening</a>。</li></ul>',5))])}const S=i(d,[["render",p]]);export{D as __pageData,S as default};
